-- Product names, prices and author terms from Control de Ventas de Comics.xlsx,
-- Control de Ventas!B8:K44. Historical stock and sales are deliberately excluded.
CREATE TABLE sales_products (
 id TEXT PRIMARY KEY, title TEXT NOT NULL,
 category TEXT NOT NULL CHECK(category IN ('comic','merchandise','other')),
 cover TEXT NOT NULL DEFAULT '', price INTEGER NOT NULL CHECK(price >= 0),
 author TEXT NOT NULL DEFAULT '', author_percent INTEGER NOT NULL DEFAULT 0 CHECK(author_percent BETWEEN 0 AND 100),
 catalog_id TEXT UNIQUE, archived INTEGER NOT NULL DEFAULT 0 CHECK(archived IN (0,1)),
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
